import{_ as e,H as E,f as p,i as n}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"开篇词 | 打通前后端技术，玩转视频平台","description":"","frontmatter":{},"headers":[{"level":2,"title":"Python 有哪些优势？","slug":"python-有哪些优势","link":"#python-有哪些优势","children":[]},{"level":2,"title":"技术学习最容易踩哪些坑？","slug":"技术学习最容易踩哪些坑","link":"#技术学习最容易踩哪些坑","children":[]},{"level":2,"title":"我是如何设计这门课程的","slug":"我是如何设计这门课程的","link":"#我是如何设计这门课程的","children":[]}],"relativePath":"Python实战·从0到1搭建直播视频平台/开篇词｜打通前后端技术，玩转视频平台.md","filePath":"Python实战·从0到1搭建直播视频平台/开篇词｜打通前后端技术，玩转视频平台.md","lastUpdated":1795533265000}'),a={name:"Python实战·从0到1搭建直播视频平台/开篇词｜打通前后端技术，玩转视频平台.md"};function i(o,t,B,s,h,l){return E(),p("div",null,[...t[0]||(t[0]=[n('<h1 id="开篇词-打通前后端技术-玩转视频平台" tabindex="-1">开篇词 | 打通前后端技术，玩转视频平台 <a class="header-anchor" href="#开篇词-打通前后端技术-玩转视频平台" aria-label="Permalink to &quot;开篇词 | 打通前后端技术，玩转视频平台&quot;">​</a></h1><p>你好，我是 Barry，很开心能在极客时间和你相遇。</p><p>先做一个自我介绍，让你能全面了解我。我目前在一家上市公司做技术研发总监，主要负责公司内部应用、C 端营销产品和 SaaS 平台开发管理工作。</p><p>这些年来我一直活跃在互联网一线项目中，曾主导电商平台、视频综合平台、人工智能教学实训平台、智能推荐平台、运维自动化部署平台、数据中台等多领域项目的研发落地工作。</p><p>除了第一份工作我做了 Java 开发，之后因为个人技术路线的规划以及公司业务的发展需求，我一直在深度应用 Python，并不断钻研前后端相关开发技术，这对我后来的职业道路影响深远。</p><h2 id="python-有哪些优势" tabindex="-1">Python 有哪些优势？ <a class="header-anchor" href="#python-有哪些优势" aria-label="Permalink to &quot;Python 有哪些优势？&quot;">​</a></h2><p>在我看来，Python 是我们拓宽技术广度，提升技术实力的强力助攻。</p><p>一方面，Python 上手丝滑，便捷友好。</p><p>接触到 Python，即是意外，也是惊喜。我早年做前端的时候，因为开发效率比较高，常常需要等后端接口开发的同学，于是我提出替他分担一些后端模块开发的工作，在这样的机会下就接触到了 Python。</p><p>当时的体感非常有趣—— Python 没有 Java 那么“重”，整个的语法和 JS 又很相似。当时能独立完成用户模块功能的开发，离不开 Python 的功劳。</p><p>另一方面，Python 生态非常完善，应用很广泛。</p><p>就拿近期非常火的 ChatGPT 来说吧，它宣告着人工智能更上了一个台阶，而人工智能主要的开发语言就是 Python。</p><p>此外，几乎所有大中型互联网企业都在使用 Python 完成各种各样的工作，Python 的落地场景涵盖 Web 应用开发、自动化运维、网络爬虫、游戏开发、数据分析等等，社区的发展也是蒸蒸日上。</p><p>因此，借助这门语言来漫游技术世界，你会接触到各种实用工具、见识丰富多样的项目，快速拓宽自己的视野。</p><h2 id="技术学习最容易踩哪些坑" tabindex="-1">技术学习最容易踩哪些坑？ <a class="header-anchor" href="#技术学习最容易踩哪些坑" aria-label="Permalink to &quot;技术学习最容易踩哪些坑？&quot;">​</a></h2><p>不过，单纯学习 Python 语言，还是无法让我们直接提升技术能力。我的技术能力就是从大量的项目和不断试错的过程中积累起来的，所以作为“过来人”，我觉得最高效的学习方法就是在实战中历练。</p><p>虽然现在的技术资料已经很丰富了，但如果东一榔头、西一棒子地盲目学习，很容易晕头转向，越学越迷茫。哪怕一时死记硬背了某些知识，还是无法知其所以然，很容易“边学边忘”。</p><p>很多技术想要吃透，必须在应用过程中深刻体会，才能知道很多“背后的门道”。比如说在技术选型时，框架如何与项目需求匹配、框架能够满足哪些功能开发，这些都是需要在开发前期深思熟虑、做足准备的。</p><p>项目实践除了能巩固知识、把零散知识串联起来，还能锻炼我们的工程思维，这些经验都会成为你未来求职、晋升的铺垫。这里我想提醒你的是，传统单一类型的项目还是很难让我们脱颖而出。所以我们更有必要花精力尝试不同类型的项目，实现质的成长。</p><p>接下来，我就和你聊聊我对这门课程的设计，以及你能从中收获什么。</p><h2 id="我是如何设计这门课程的" tabindex="-1">我是如何设计这门课程的 <a class="header-anchor" href="#我是如何设计这门课程的" aria-label="Permalink to &quot;我是如何设计这门课程的&quot;">​</a></h2><p>课程里最有特色的就是全程围绕项目实践来进行。项目选择上，我也是颇费了一番心思，最终确定带你一起做一个在线视频平台。之所以选择做这样一个项目，而不是带你做一个“管理后台”或“用户管理”的初级项目，主要是从精度和广度考虑的。</p><p>近几年国内视频平台热度很高，视频平台成为风口上的行业，短视频、中视频和长视频百花齐放。人们可以通过视频快速获取自己需要的内容，这种模式比其他媒介更加高效、便捷、更前沿。肥沃的流量背后是巨大的利润，也意味着相关人才的强烈需求。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" alt=""></a></p><ul><li><p>图片来源 <a href="https://www.stcn.com/article/detail/828922.html" target="_blank" rel="noreferrer">https://www.stcn.com/article/detail/828922.html</a></p></li><li><p>《2023 中国网络视听发展研究报告》显示，截至 2022 年 12 月，我国网络视听用户规模达10.40 亿，超过即时通讯（10.38 亿），成为第一大互联网应用。其中，短视频领域市场规</p></li><li><p>模为 2928.3 亿，占比为 40.3%，是产业增量的主要来源；其次是网络直播领域，市场规模为 1249.6 亿，占比为 17.2%，成为拉动网络视听行业市场规模的重要力量。</p></li></ul><p>我们的时间精力都很宝贵，学习的时候更要关注投入产出比。只有在线视频直播平台这样的项目，才能更加充分地锻炼、提升我们的技术实力，最终实现出来也更有成就感。</p><p>这个项目里，前端我们前端采用主流 Vue 框架，告别传统陈旧 Web 框架，同时还纳入了当下前沿的 Element 组件库，它具备更高效的开发能力。后端框架选用 Flask，这是一个轻量易上手的框架。这些框架更加热门、技术含金量也更高。</p><p>相信这个从 0 到 1 造轮子的过程，能让你受益匪浅。一旦掌握，不光是课程里的项目，日常Web 开发例如 CRM、数据中台、小程序等等应用，凡是与 Python 后端开发相关的项目，你应对起来都会游刃有余。</p><p>项目中涵盖更多元的应用场景，还加入了时下流行的直播模块。我还特意录了一个小视频，演示我们要实现的平台长什么样、有什么功能，你可以看看后面这个视频，做进一步了解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/3.png" alt=""></a></p><p>接下来我们一起来了解各个篇章的内容。</p><p>课程前导篇</p><p>课程遵循由浅入深的原则，前导篇我会带你一起做一个预热，带你了解 Python 和 Vue 的基础知识。这个部分我安排了很多代码实例供你练习，还会提供很多我亲测有效的技术学习方法。</p><p>学完这个部分，你将初步体验到 Python 和 Vue 的魅力。如果你是新手，前导篇有助于你消除心理负担、更轻松地跟上后续的进阶学习。如果你是老手，也可以借此查漏补缺、巩固知识。</p><p>前端实战篇</p><p>这个篇章我们会完成架构设计和前端模块开发。我们会从需求分析开始，逐一梳理平台的功能有哪些、如何设计模块。这有助于你锻炼工程思维，学会如何根据实际业务选择匹配的框架。</p><p>之后，我们会按照架构设计搭建 Vue 框架、设计路由、应用 Element 组件库和数据可视化ECharts 工具，一步步完成功能模块开发、项目打包与优化。学完这个部分，你就掌握了 Vue框架的开发能力和第三方组件库的应用能力，二者结合，即可快速实现前端需求开发。</p><p>后端实战篇</p><p>后端实战部分，整体的设计逻辑和前端模块相似。从代码设计到具体功能的模块接口开发的关键环节都有涉及，核心知识点包括 Flask 项目搭建、正则匹配路由、异常捕获、Flask-RESTful 开发实践、Flask 认证机制，还有数据库的应用。</p><p>深度体验独立搭建和后端开发的完整链路以后，你将掌握 Python 后端开发的核心技能。换句话说，就是具备了项目后端开发从 0 到 1 的能力，能够灵活应用框架技术来应对应对多种类型的项目需求。</p><p>直播模块篇</p><p>直播模块核心是整个项目里最有特色的部分，我会带你实现一个小负载的直播应用。</p><p>麻雀虽小，五脏俱全，这个应用涵盖了平台直播系统后台搭建、HLS 协议直播、推拉流、串流码与控制器以及直播功能的完整实现。这部分能让我们在前后端技术开发实现的基础上，再做一次飞跃，让我们这次项目开发实践的体验更加丰富多维，拓展你的技术领域，丰富项目经验，也为你后续钻研直播开发打好基础。</p><p>总结篇</p><p>复盘有助于我们巩固学习效果，提炼学习方法。整个项目开发完成以后，我还会带你总结回顾，沉淀经验，同时也会和你聊聊全栈工程师职业发展的路线和建议。</p><p>我把课程里的重要环节和知识点整理成了一张知识导图，供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/4.jpeg" alt=""></a></p><p>整个课程学完以后，你会收获 Python 项目开发的完整体验，掌握前后端和数据库应用的核心技术。除了技术方面的收获，我还会和你分享很多实操经验和分析推导方法，帮助你系统提升业务理解、分析能力，这样不但能让你向独立开发的道路更进一步，还能培养你未来自学高级架构的能力。</p><p>最后，我再分享几条学习这门课程的建议吧。如果你能应用和坚持下去，学习的效果一定会更好。</p><p>第一，保持“寻根究底”的深挖心态。学习的时候只停留在应用层看似轻松，但却会错过很多深层次的探索过程，很多时候这种探索能让我们得到更有价值的东西。</p><p>第二，坚持动手练习。课程的实操项目只用眼睛看是无法真正理解的，一定要跟着我勤加练习，这样才能扎实地掌握。相信我，坚持下来，这个过程中你会有意想不到的收获感和喜悦感。</p><p>最后就是不给自己设限，勤于思考。这里的思考不只是理解技术，还包括准确深刻地理解业务，并通过记笔记、做总结等方式记录自己的所思所得。这不但有助于我们日常提升技术实力，还能在面试里成为重要加分项。总之，你的总结思考能力越强，在技术道路上你就会走得越快越稳，事半功倍。</p><p>我希望这门课程不仅能帮你提升技术深度和广度，还能帮你掌握不同开发语言学习和技能提升的实用方法，让你具备广阔视野，探索更多可能。最后，祝我们都能在技术领域上越走越远，勇攀高峰。</p><p>一起玩转视频平台，在实战中精进技术，学习之旅即将开启，一起加油吧！</p>',55)])])}const c=e(a,[["render",i]]);export{A as __pageData,c as default};
